const cloudModules=trackDefinitions.cloud.modules;
const aiModules=trackDefinitions.ai.modules;
const articleById=id=>articles.find(a=>a.id===id);
const trackForModule=id=>moduleFor(id)?.track;
function chapterLink(a){return `<a class="chapter-row" href="${articleURL(a.id)}"><div class="chapter-top"><span>CHAPTER ${a.number}</span><span>${a.level} · ${progress[a.id]?'已读 ✓':'开始阅读 ↗'}</span></div><h2>${a.title}</h2><p>${a.desc}</p></a>`}
function learningContract(a){const content=`<div class="learning-contract"><strong>读完这一章，你应该能</strong><ul>${a.objectives.map(t=>'<li>'+t+'</li>').join('')}</ul><p><b>前置知识</b>${a.prereq}</p><p class="evidence-note">约 ${a.minutes} 分钟 · ${a.baseline||'训练代码基线 PyTorch 2.5.1'} · <a href="#/labs">实验验证范围 ↗</a></p></div>`;return '<details class="guided-contract"><summary>先修、学习目标与验证范围 · 约'+a.minutes+'分钟</summary>'+content+'</details>'}
function mobileContents(a){return `<details class="mobile-contents"><summary>章节导航与本文目录</summary><a href="#/module/${a.module}">← 返回本模块目录</a>${conceptTOCLink(articleURL(a.id))}${a.sections.map((s,i)=>`<a href="${articleURL(a.id)}#section-${i+1}">${i+1}. ${s[0]}</a>`).join('')}</details>`}
function courseIntro(){return `<div class="course-intro"><span class="small-badge">训练专题 / 10 章</span><h2>先理解一步训练，再走向多机多卡。</h2><p>从资源预算、数据与通信，到完整DDP程序、两机四卡手册和恢复对照。同一份实验贯穿执行机制与故障验证。</p><div class="course-links"><a class="btn" href="#/article/gpu-cluster">从全景开始 →</a><a class="btn secondary" href="#/labs">实验与验证记录 ↗</a></div><small>CPU/Gloo已有实测；真实GPU/NCCL与Kubernetes仍需目标环境验证。</small></div>`}
function sectionGroup(list){return trainingGroups.map((g,i)=>`<section class="course-group"><div class="group-label">${g}</div>${list.filter(a=>a.group===i).map(chapterLink).join('')}</section>`).join('')}
function simplePage(title,kicker,desc,body){document.title=title+' · InfraGuide';$('#app').innerHTML=`<main id="main" class="container collection" tabindex="-1"><div class="breadcrumb"><a href="#/">知识库</a><span>／ ${title}</span></div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="description">${desc}</p>${body}</main>${footer()}`}
function trackCard(key){const t=trackDefinitions[key],n=articles.filter(a=>t.modules.includes(a.module)).length;return `<a class="track-card ${key}" href="#/track/${key}"><span class="track-index">${{cloud:'01',ai:'02',agent:'03'}[key]} / ${n} 章</span><h2>${t.label}<span>↗</span></h2><h3>${t.subtitle}</h3><p>${t.story}</p><div class="track-steps">${{cloud:'请求 → 资源 → 交付 → 恢复',ai:'数据 → 训练 → 评估 → 推理',agent:'目标 → 工具 → 状态 → 验收'}[key]}</div></a>`}
function homePage(){document.title='InfraGuide · Cloud / AI / Agent';$('#app').innerHTML=`<main id="main" class="container" tabindex="-1"><section class="infra-hero"><div class="eyebrow"><span class="dot"></span> 给初学者与面试准备者的基础设施指南</div><div class="hero-grid"><div><h1>先看懂全貌，<br>再把系统讲清楚。</h1><p>Cloud、AI、Agent Infra，各自解决什么问题，彼此怎样连接？从快速大纲开始，用具体例子理解机制，沿核心问题复习，再进入章节与实战。</p><div class="buttons"><a class="btn" href="/outline/">30分钟，快速看懂大纲 →</a><a class="btn secondary" href="/interview/">面试复习与追问 ↗</a></div></div><div class="reading-sample"><div class="sample-label">从一个问题，读懂一组机制</div><a href="#/article/agent-recovery"><strong>工具已经执行，<br>为什么任务还没完成？</strong><span>理解提交间隙 → 画出状态流 → 运行崩溃实验</span></a><div class="sample-result"><span>ATTEMPTS <b>2</b></span><span>EFFECTS <b>1</b></span><small>本地恢复实验 · 附代码与验证记录</small></div></div></div></section><section class="track-grid" aria-label="三条学习路线">${Object.keys(trackDefinitions).map(trackCard).join('')}</section><div class="shared-line"><b>共同的工程底座</b><span>计算与数据路径 · 身份与权限 · 可观测性 · 版本与恢复</span><a href="#/article/cloud-overview">建立系统地图 →</a></div><div class="entry-grid"><a href="#/start"><small>START</small><strong>第一次来，从这里开始 →</strong><span>选大纲、面试或完整学习路线</span></a><a href="#/labs"><small>LAB</small><strong>运行代码与实验 →</strong><span>下载程序，核对预期结果</span></a><a href="#/problems"><small>DIAGNOSIS</small><strong>带着问题查机制 →</strong><span>从现象找到排查入口</span></a><a href="#/about"><small>QUALITY</small><strong>查看内容与证据标准 →</strong><span>来源、版本和验证边界</span></a></div><section class="section"><div class="section-heading"><div><h2>完整课程目录</h2><p>${modules.length} 个模块 · ${articles.length} 章 · 每章包含前置知识、机制解释与迁移练习</p></div><div class="view-tabs" aria-label="知识库筛选">${[['all','全部'],['cloud','Cloud'],['ai','AI'],['agent','Agent']].map(([id,t])=>`<button data-filter="${id}" aria-pressed="${filter===id}" class="${filter===id?'active':''}">${t}</button>`).join('')}</div></div><div class="module-grid" id="module-grid"></div></section><section class="section"><div class="section-heading"><div><h2>沿着一个场景，把机制读懂</h2><p>三个渐进样章：先建立直觉，再跟着事件、状态与数字走一遍。</p></div></div><div class="example-grid">${[['cloud-overview','一次请求','程序启动了，服务为什么仍然不可用？'],['model-serving','三个token','每一步究竟输入了什么、缓存了什么？'],['agent-runtime','一份报告','从模型提议到真实产物，还缺哪些环节？']].map(([id,n,t])=>`<a href="#/article/${id}"><span>${n}</span><h3>${t}</h3><small>打开推导与实验 →</small></a>`).join('')}</div></section><section class="home-principle"><h2>信息量来自解释深度。</h2><p>每个知识点都回到具体系统：它解决什么问题，怎样工作，何时失效，以及用什么证据判断。图、公式与代码共同推进同一条推理。</p><a href="#/about">我们的内容标准 →</a></section></main>${footer()}`;renderModuleGrid()}
function trackPage(kind){if(kind==='cloud')cloudKnowledgePage(moduleFor('compute'));else infraKnowledgePage(moduleFor(kind==='ai'?'model-foundations':'agent'));}

function sidebarView(moduleId, current) {
 const track = moduleFor(moduleId).track;
 const topicModules = modules.filter(module => module.track === track);
 const topicArticles = articles.filter(article => trackForModule(article.module) === track);
 const read = topicArticles.filter(article => progress[article.id]).length;
 const label = trackDefinitions[track]?.label || '综合实战';
 const sections = topicModules.map(module => {
  const active = module.id === moduleId;
  const chapters = topicArticles.filter(article => article.module === module.id);
  const links = chapters.map((article, index) => {
   const startsGroup = article.group !== undefined && (!index || chapters[index-1].group !== article.group);
   const group = startsGroup ? '<div class="side-group">'+trainingGroups[article.group]+'</div>' : '';
   const selected = article.id === current ? 'class="current" aria-current="page"' : '';
   return `${group}<a href="${articleURL(article.id)}" ${selected}>${article.number} ${article.title}${progress[article.id]?'<span class="read-mark">✓</span>':''}</a>`;
  }).join('');
  return `<details ${active?'open':''}><summary><a href="/module/${module.id}/" ${active&&!current?'class="current" aria-current="page"':''}><span>${module.n}</span>${module.name}</a></summary><div class="side-links">${links}</div></details>`;
 }).join('');
 return `<aside class="sidebar" aria-label="章节导航"><a class="side-home" href="/outline/">← 全站大纲</a>
  <div class="side-heading"><span>${label} · 领域与章节</span><span>${topicArticles.length} 章</span></div>${sections}
  <div class="side-progress"><div><span>本主题阅读进度</span><b>${read} / ${topicArticles.length}</b></div>
   <div class="progress-bar"><span style="width:${read/topicArticles.length*100}%"></span></div><span>仅保存在当前浏览器</span></div></aside>`;
}
function moduleOverview(m,list){return `<div class="module-intro"><b>这一模块的学习出口</b><ul>${m.outcomes.map(t=>'<li>'+t+'</li>').join('')}</ul><span>${list.length}章 · 先理解机制，再用问题和实验检验理解</span></div>`}
function relatedReading(a){if(!a.related?.length)return '';return `<section class="related-reading"><h2>把这一章连回系统</h2>${a.related.map(id=>`<a href="${articleURL(id)}"><span>${articleById(id).number}</span>${articleById(id).title}<b>↗</b></a>`).join('')}</section>`}
function roadmapPage(){const stages={cloud:cloudLearningStages,ai:[['模型与GPU原理',['transformer-model','tokenization-embedding','attention-mechanics','transformer-block','position-encoding','autograd-training']],['GPU执行、IO与层内并行',['gpu-execution','roofline-model','flash-attention-io','tensor-parallel-math']],['训练系统与资源模型',['gpu-cluster','distributed-training','gpu-memory']],['执行、恢复与作业平台',['ddp-code','training-communication','data-pipeline','multinode-lab','checkpoint-recovery','training-performance','training-platform','gpu-scheduling','kubernetes-training']],['推理、评估与发布',['model-serving','inference-performance','ai-lifecycle','training-lab']]],agent:[['任务与执行边界',['distributed-systems','agent-runtime','agent-security','agent-sandbox']],['恢复、上下文与评估',['agent-recovery','agent-memory','agent-evaluation']],['持久工作流与知识检索',['durable-workflows','agent-retrieval']],['轨迹、隔离与综合验收',['agent-observability','kairo-practice','production-readiness']]]};simplePage('选择你的学习路线','THREE TRACKS · SHARED FOUNDATIONS','根据已有基础选择起点。三条路线互相连接，Agent不以完成GPU训练为前提。',`<div class="route-selector">${Object.keys(trackDefinitions).map(k=>`<a href="#/roadmap?track=${k}">${trackDefinitions[k].label} ↓</a>`).join('')}</div>${Object.entries(stages).map(([k,ss])=>`<section class="route-block" id="route-${k}"><div class="route-title"><span>${trackDefinitions[k].label}</span><h2>${trackDefinitions[k].subtitle}</h2><p>${trackDefinitions[k].story}</p></div>${ss.map(([title,ids],i)=>`<div class="roadmap-step"><span class="step-num">0${i+1}</span><div><h3>${title}</h3>${k==='cloud'?cloudStageStudyHTML(i):infraStageStudyHTML(k,i)}${ids.map(id=>`<a href="${articleURL(id)}">${articleById(id).number} ${articleById(id).title}${progress[id]?' ✓':' ↗'}</a>`).join('')}</div></div>`).join('')}<a class="inline-link" href="#/track/${k}">查看这条路线的全部章节 →</a></section>`).join('')}<div class="track-note"><b>用学习出口判断是否继续</b><p>能画出系统路径、解释一个反例、独立运行实验并核对结果，再进入下一阶段。阅读勾选记录进度；它不替代工程能力验收。</p></div>`);const key=new URLSearchParams(location.search).get('track');if(trackDefinitions[key])requestAnimationFrame(()=>document.getElementById('route-'+key)?.scrollIntoView())}
function labsPage(){renderLabCatalog()}
const problemItems=[['服务已经启动，用户却访问失败','沿DNS、连接、TLS和HTTP定位最后成功阶段。','vpc-network','Cloud'],['机器CPU不高，请求仍然很慢','区分执行时间、连接池与下游等待。','linux-resource','Cloud'],['集群还有GPU，Pod却无法调度','检查资源形状、单节点可行性与放置约束。','scheduling-resources','Cloud'],['readiness失败，为什么进程没重启','分清启动、存活和流量资格。','kubernetes-basics','Cloud'],['回滚镜像后，行为没有恢复','检查配置、数据与外部产物版本。','delivery','Cloud'],['多个实例的p99怎么合并','回到分布与可聚合直方图。','observability','SRE'],['备份成功，却无法恢复服务','验证清单、提交点和实际消费者。','storage-recovery','SRE'],['训练OOM，增加GPU仍没解决','先算状态与激活，再判断复制还是分片。','gpu-memory','AI'],['多机启动等待或通信超时','找最早异常，再区分会合与数据通信。','training-communication','AI'],['GPU经常等待数据','用三组输入对照定位关键路径。','data-pipeline','AI'],['保存了检查点，却不能继续','核对状态、规模、进度和数据顺序。','checkpoint-recovery','AI'],['权重放得下，并发却上不去','按上下文和并发估算KV容量。','model-serving','AI'],['首token延迟报告互相矛盾','统一客户端与服务端计时边界。','inference-performance','AI'],['工具已生效，任务还停在运行中','检查提交间隙与接收方幂等语义。','agent-recovery','Agent'],['工具结果要求提升权限','把外部文本与可信授权分开。','agent-security','Agent'],['Agent说成功，实际产物却不对','用环境断言验收任务结果。','agent-evaluation','Agent']];
function problemsPage(){simplePage('问题索引','START WITH A SYMPTOM','先选择现象，再通过证据判断原因。这里提供排查入口，不预先替你认定根因。',`<div class="problem-list">${problemItems.map(([t,d,id,tag])=>`<a href="${articleURL(id)}"><span class="tag">${tag}</span><div><h2>${t}</h2><p>${d}</p></div><b>↗</b></a>`).join('')}</div>`)}
function editorialPage(){simplePage('内容与证据标准','EXPLAIN THE SYSTEM · SHOW THE EVIDENCE','高信息量来自清晰的因果链：知道为什么，理解怎样工作，能够计算或验证，再讨论选择。',`<section class="quality-section"><h2>同一网站，三条独立主线</h2><div class="track-grid">${Object.keys(trackDefinitions).map(trackCard).join('')}</div><p>Cloud建立系统底座；AI展开训练与推理；Agent研究工具执行、状态与任务验收，并连接Kairo实践。可靠性、权限、版本和成本贯穿三条路线，综合实战连接跨层依赖。</p></section><section class="quality-section"><h2>一章内容怎样展开</h2><p>默认读者第一次接触这个领域。入口和每章都先介绍基本对象，接着解释对象之间的关系，再讲机制、推导和边界，最后进入案例与代码。专业词在进入推理前给出含义；图、表、代码围绕同一组对象与数字展开，最后改变条件检验理解。</p>${trainingTable(['阅读顺序','必须回答的问题','读者得到什么'],[['对象与关系','概念是什么，彼此怎样连接，为什么需要它','学习起点与全局地图'],['机制与因果','输入如何经过状态变化成为输出','可以解释的执行路径'],['走通一个例子','具体数字、事件或代码怎样对应机制','可复查的推导'],['选择与失败','什么时候成立，什么条件下失效','工程判断与反例'],['练习与验证','换一个条件，你能否独立解释','迁移能力与证据']])}<p>本站文章、图和实验代码独立编写。领域知识、详细章节与实验相互连接，学习后可以改变条件，重新解释结果。</p></section><section class="quality-section"><h2>当前交付与验证边界</h2><p>共${articles.length}章：Cloud 28章、AI 25章、Agent 10章、综合实战3章。全部提供前置知识、学习出口、机制正文、迁移练习和来源。章节齐备与真实环境已验证是两种不同状态。</p><p>本地系统、SQLite恢复、批处理、CPU/Gloo及真实Terraform计划实验附环境、结果与代码摘要；GitOps模型另标注范围。真实GPU、集群部署、生产模型压测和Kairo集成仍需目标环境验收。<a href="#/labs">查看逐项验证记录 →</a></p></section><section class="quality-section"><h2>内容维护的质量门槛</h2>${trainingTable(['门槛','检查方式'],[['准确性','优先官方资料，注明产品语义、版本与假设'],['可理解性','先定义对象与关系，再有连续推导、例子和反例'],['可复现性','完整代码、命令、依赖、预期结果与源码摘要一致'],['可审查性','保留失败边界，不用CPU结果推断GPU或集群结果'],['可维护性','修改实验后重跑相关验证；版本变化复查对应事实']])}<p>当前优先按读者理解卡点，逐章深化连续解释、手算例子与反例；有合适环境时，再补真实GPU、Kubernetes和Kairo验收。新章节按问题价值增加，已有章节按错误、过时信息和验证缺口持续修订。</p></section><section class="quality-section"><h2>阅读与隐私</h2><p>学习路线按依赖组织；目录按系统领域组织；实验室提供代码和证据；问题索引连接现象与机制。搜索覆盖正文，阅读勾选与主题仅保存在当前浏览器。</p></section>`)}
